  7	/// <summary>
  8	/// F&amp;F Approval — stages 12 and 13 of the exit flow.
  9	///
 10	/// A separate screen from the settlement itself on purpose: a different person with different
 11	/// rights signs this off, and they should see the case read-only rather than in an editable
 12	/// form where a stray keystroke changes what they are approving.
 13	///
 14	/// Approving is the moment the money moves: the amounts are pushed into the chosen payroll
 15	/// month and the recovered loan schedule is closed. All of that lives in
 16	/// <see cref="FNFSettlementService.ApproveCase"/> so it happens in one transaction and can be
 17	/// tested without the site.
 18	/// </summary>
 19	public partial class Payroll_FNFApproval : System.Web.UI.Page
 20	{
 21	    // Session, never ViewState: a DevExpress callback does not round-trip ViewState.
 22	    private long CurrentCaseId
 23	    {
 24	        get { return Session["APR_CaseId"] != null ? Convert.ToInt64(Session["APR_CaseId"]) : 0; }
 25	        set { Session["APR_CaseId"] = value; }
 26	    }
 27	
 28	    private long CompanyId
 29	    {
 30	        get { return Session["CompanyID"] != null ? Convert.ToInt64(Session["CompanyID"]) : 0; }
 31	    }
 32	
 33	    private int UserId
 34	    {
 35	        get { return Session["UserID"] != null ? Convert.ToInt32(Session["UserID"]) : 0; }
 36	    }
 37	
 38	    private static SqlConnection CreateConnection()
 39	    {
 40	        return new SqlConnection(DbConnectionFactory.GetConnectionString());
 41	    }
 42	
 43	    private static string HostNameCapped()
 44	    {
 45	        string name = null;
 46	        try { name = System.Net.Dns.GetHostName(); } catch { }
 47	        if (string.IsNullOrEmpty(name)) return string.Empty;
 48	        return name.Length > 50 ? name.Substring(0, 50) : name;
 49	    }
