112	    protected void ApGridView_CustomButtonCallback(object sender, ASPxGridViewCustomButtonCallbackEventArgs e)
113	    {
114	        if (e.ButtonID != "btnOpen") return;
115	        ApGridView.JSProperties["cpOpenId"] =
116	            Convert.ToString(ApGridView.GetRowValues(e.VisibleIndex, "FNFSettlementID"));
