119	    // -- Dispatch -------------------------------------------------------------
120	
121	    protected void ApPanel_Callback(object sender, CallbackEventArgsBase e)
122	    {
123	        string[] parts = (e.Parameter ?? string.Empty).Split('|');
124	        if (parts.Length < 2) return;
125	
126	        long id;
127	        long.TryParse(parts[1], out id);
128	
129	        try
130	        {
131	            switch (parts[0])
132	            {
133	                case "Load":    LoadCase(id);    break;
134	                case "Approve": HandleApprove(); break;
135	                case "Reject":  HandleReject();  break;
136	            }
137	        }
138	        catch (Exception ex)
139	        {
140	            ErrorLogHelper.Log(ex, "FNFApproval." + parts[0]);
141	            // ApproveCase throws with a sentence meant for the user (wrong status, someone
142	            // else changed it), so show that rather than the generic message.
143	            ApPanel.JSProperties["cpMsg"] = ex is InvalidOperationException
144	                ? ex.Message
145	                : ErrorLogHelper.FriendlyMessage;
146	        }
147	    }
148	
149	    private void LoadCase(long id)
150	    {
151	        if (id <= 0) return;
152	
153	        const string sql = @"
154	            SELECT F.*,
155	                   LTRIM(ISNULL(' ' + NULLIF(LTRIM(RTRIM(EM.FirstName)),''), '') + ISNULL(' ' + NULLIF(LTRIM(RTRIM(EM.FatherName)),''), '') + ISNULL(' ' + NULLIF(LTRIM(RTRIM(EM.LastName)),''), '')) AS EmployeeName,
156	                   ISNULL(EM.Code, '')      AS EmployeeCode,
157	                   ISNULL(U.UserName, '')   AS PreparedBy,
158	                   (SELECT COUNT(*) FROM dbo.HR_FNFCheck K
159	                    WHERE K.FNFSettlementID = F.FNFSettlementID AND K.CheckKind = 'Verification'
160	                      AND K.IsRequired = 1 AND ISNULL(K.Result,'') NOT IN ('Pass','NA')) AS VerifyOutstanding
161	            FROM   dbo.HR_FNFSettlement F
162	            LEFT   JOIN dbo.HR_EmployeeMaster EM ON EM.EmployeeMasterID = F.EmployeeMasterID
163	            LEFT   JOIN dbo.HR_UserMaster U      ON U.UserMasterID      = F.EntryUserMasterID
164	            WHERE  F.FNFSettlementID = @Id AND F.Status = 1";
165	
166	        DataRow row = null;
167	        using (SqlConnection conn = CreateConnection())
168	        using (var cmd = new SqlCommand(sql, conn))
169	        {
170	            cmd.Parameters.AddWithValue("@Id", id);
171	            var dt = new DataTable();
172	            using (var da = new SqlDataAdapter(cmd)) da.Fill(dt);
173	            if (dt.Rows.Count > 0) row = dt.Rows[0];
174	        }
175	
176	        if (row == null)
177	        {
178	            ApPanel.JSProperties["cpMsg"] = "That case no longer exists.";
179	            ApPanel.JSProperties["cpReloadList"] = true;
180	            return;
181	        }
182	
183	        CurrentCaseId = id;
184	
185	        // Seed the approval parameters from a fresh, NON-PERSISTING calculation, so the policy
186	        // column reflects the rules as they stand now and nothing the approver does can alter
187	        // the preparer's stored figures.
188	        try
189	        {
190	            using (SqlConnection conn = CreateConnection())
191	            {
192	                conn.Open();
193	                using (SqlTransaction tx = conn.BeginTransaction())
194	                {
195	                    try
196	                    {
197	                        FNFSettlementService.Config cfg = FNFSettlementService.LoadConfig(
198	                            conn, tx, Convert.ToInt64(row["CompanyMasterID"]));
199	                        FNFSettlementService.Result res = FNFSettlementService.Calculate(
200	                            conn, tx, id, UserId, false);
201	                        FNFSettlementService.SeedApprovalParameters(conn, tx, id, res, cfg);
202	                        tx.Commit();
203	                    }
204	                    catch { try { tx.Rollback(); } catch { } throw; }
205	                }
206	            }
207	        }
208	        catch (Exception ex)
209	        {
210	            // A case with no config or no salary record must still be reviewable.
211	            ErrorLogHelper.Log(ex, "FNFApproval.SeedParams");
212	        }
213	
214	        // Default the payroll month to the last working month - that is where the settlement
215	        // belongs, and it is what the preparer's own final-salary line refers to.
216	        DateTime target = row["LastWorkingDate"] != DBNull.Value
217	            ? Convert.ToDateTime(row["LastWorkingDate"])
218	            : DateTime.Today;
219	
220	        if (row["SettlementMonth"] != DBNull.Value && row["SettlementYear"] != DBNull.Value)
221	        {
222	            cmbMonth.Value = Convert.ToInt32(row["SettlementMonth"]);
223	            spnYear.Value = Convert.ToInt32(row["SettlementYear"]);
224	        }
225	        else
226	        {
227	            cmbMonth.Value = target.Month;
228	            spnYear.Value = target.Year;
229	        }
230	
231	        memReject.Text = string.Empty;
232	        litSummary.Text = BuildSummaryHtml(row);
233	        litBanner.Text = BuildBannerHtml(row);
234	        litMonthHint.Text =
235	            "<span class=\"ap-kv\">The settlement is pushed into this month as salary-head "
236	          + "overrides, so Salary Generate for it will carry the amounts.</span>";
237	
238	        LineGrid.DataBind();
239	        ParamGrid.DataBind();
240	
241	        ApPanel.JSProperties["cpOpen"] = "1";
242	    }
