352	    protected void ParamGrid_RowUpdating(object sender, DevExpress.Web.Data.ASPxDataUpdatingEventArgs e)
353	    {
354	        e.Cancel = true;
355	        try
356	        {
357	            if (CurrentCaseId <= 0) { ParamGrid.CancelEdit(); return; }
358	
359	            const string sql = @"
360	                UPDATE dbo.HR_FNFCheck
361	                SET    Result = @Result, Remarks = @Remarks,
362	                       ActionedByUserMasterID = @UserID, ActionedOn = GETDATE()
363	                WHERE  FNFCheckID = @RowId AND FNFSettlementID = @CaseId
364	                  AND  CheckKind = 'ApprovalParameter'";
365	
366	            using (SqlConnection conn = CreateConnection())
367	            using (var cmd = new SqlCommand(sql, conn))
368	            {
369	                cmd.Parameters.AddWithValue("@Result", e.NewValues["Result"] ?? (object)DBNull.Value);
370	                cmd.Parameters.AddWithValue("@Remarks", e.NewValues["Remarks"] ?? (object)DBNull.Value);
371	                cmd.Parameters.AddWithValue("@UserID", UserId);
372	                cmd.Parameters.AddWithValue("@RowId", Convert.ToInt64(e.Keys[ParamGrid.KeyFieldName]));
373	                cmd.Parameters.AddWithValue("@CaseId", CurrentCaseId);
374	                conn.Open();
375	                cmd.ExecuteNonQuery();
376	            }
377	
378	            ParamGrid.CancelEdit();
379	        }
380	        catch (Exception ex)
381	        {
382	            ErrorLogHelper.Log(ex, "FNFApproval.ParamUpdate");
383	            ApPanel.JSProperties["cpMsg"] = ErrorLogHelper.FriendlyMessage;
384	        }
385	    }
