 69	    private DataTable LoadPending()
 70	    {
 71	        // Scoped in the one query the grid runs, so nothing downstream can widen it. An admin
 72	        // sees the company; anyone else sees only what they are the named approver on.
 73	        string scope = RoleHelper.IsAdmin(Session["UserRole"])
 74	            ? string.Empty
 75	            : " AND F.ApproverUserMasterID = @UserID ";
 76	
 77	        string sql = @"
 78	            SELECT F.FNFSettlementID, F.CaseNo, F.LastWorkingDate,
 79	                   ISNULL(F.TotalEarnings,0)   AS TotalEarnings,
 80	                   ISNULL(F.TotalDeductions,0) AS TotalDeductions,
 81	                   ISNULL(F.NetPayable,0)      AS NetPayable,
 82	                   LTRIM(ISNULL(' ' + NULLIF(LTRIM(RTRIM(EM.FirstName)),''), '') + ISNULL(' ' + NULLIF(LTRIM(RTRIM(EM.FatherName)),''), '') + ISNULL(' ' + NULLIF(LTRIM(RTRIM(EM.LastName)),''), '')) AS EmployeeName,
 83	                   ISNULL(EM.Code, '')         AS EmployeeCode,
 84	                   ISNULL(U.UserName, '')      AS PreparedBy
 85	            FROM   dbo.HR_FNFSettlement F
 86	            LEFT   JOIN dbo.HR_EmployeeMaster EM ON EM.EmployeeMasterID = F.EmployeeMasterID
 87	            LEFT   JOIN dbo.HR_UserMaster U      ON U.UserMasterID      = F.EntryUserMasterID
 88	            WHERE  F.Status = 1
 89	              AND  F.CompanyMasterID = @CompanyID
 90	              AND  F.WorkflowStatus = @Submitted " + scope + @"
 91	            ORDER  BY F.FNFSettlementID DESC";
 92	
 93	        var table = new DataTable();
 94	        try
 95	        {
 96	            using (SqlConnection conn = CreateConnection())
 97	            using (var cmd = new SqlCommand(sql, conn))
 98	            {
 99	                cmd.Parameters.AddWithValue("@CompanyID", CompanyId);
100	                cmd.Parameters.AddWithValue("@Submitted", FNFCaseService.StatusSubmitted);
101	                cmd.Parameters.AddWithValue("@UserID", UserId);
102	                using (var da = new SqlDataAdapter(cmd)) da.Fill(table);
103	            }
104	        }
105	        catch (Exception ex)
106	        {
107	            ErrorLogHelper.Log(ex, "FNFApproval.LoadPending");
108	        }
109	        return table;
110	    }
