253	    private string BuildSummaryHtml(DataRow row)
254	    {
255	        decimal net = row["NetPayable"] == DBNull.Value ? 0m : Convert.ToDecimal(row["NetPayable"]);
256	        string netClass = net < 0 ? "ap-net neg" : "ap-net";
257	        string netLabel = net < 0 ? "Recoverable from employee" : "Net Payable";
258	
259	        var sb = new System.Text.StringBuilder();
260	        sb.Append("<table class=\"ap-kv\" style=\"border-collapse:collapse\"><tr>");
261	        sb.Append(Cell("Case No.", row["CaseNo"]));
262	        sb.Append(Cell("Employee", row["EmployeeName"]));
263	        sb.Append(Cell("Code", row["EmployeeCode"]));
264	        sb.Append(Cell("Last Working Day", row["LastWorkingDate"] == DBNull.Value
265	            ? null : (object)Convert.ToDateTime(row["LastWorkingDate"]).ToString("dd-MM-yyyy")));
266	        sb.Append(Cell("Prepared By", row["PreparedBy"]));
267	        sb.Append("</tr><tr>");
268	        sb.Append(Cell("Total Earnings", Convert.ToDecimal(row["TotalEarnings"] == DBNull.Value ? 0m : row["TotalEarnings"]).ToString("n2")));
269	        sb.Append(Cell("Total Deductions", Convert.ToDecimal(row["TotalDeductions"] == DBNull.Value ? 0m : row["TotalDeductions"]).ToString("n2")));
270	        sb.Append(Cell("Per-day Basis", row["PerDayRateBasis"]));
271	        sb.Append("<td style=\"padding:4px 16px 4px 0;white-space:nowrap\"><span style=\"color:#777\">")
272	          .Append(HttpUtility.HtmlEncode(netLabel)).Append("</span><br /><span class=\"")
273	          .Append(netClass).Append("\">").Append(Math.Abs(net).ToString("n2")).Append("</span></td>");
274	        sb.Append("</tr></table>");
275	        return sb.ToString();
276	    }
