278	    private string BuildBannerHtml(DataRow row)
279	    {
280	        int outstanding = Convert.ToInt32(row["VerifyOutstanding"]);
281	        string status = Convert.ToString(row["WorkflowStatus"]);
282	
283	        if (!string.Equals(status, FNFCaseService.StatusSubmitted, StringComparison.OrdinalIgnoreCase))
284	        {
285	            return "<div class=\"ap-banner blocked\">This case is " + HttpUtility.HtmlEncode(status)
286	                 + ", not Submitted, so it cannot be approved from here.</div>";
287	        }
288	
289	        if (outstanding > 0)
290	        {
291	            return "<div class=\"ap-banner blocked\">" + outstanding + " verification check(s) are "
292	                 + "still not Pass on the preparer's side. Approving is blocked until they are.</div>";
293	        }
294	
295	        return "<div class=\"ap-banner ready\">Verified and submitted &mdash; ready for your "
296	             + "decision.</div>";
297	    }
