387	    // -- Decisions ------------------------------------------------------------
388	
389	    private void HandleApprove()
390	    {
391	        if (CurrentCaseId <= 0) return;
392	
393	        if (cmbMonth.Value == null || spnYear.Value == null)
394	        {
395	            ApPanel.JSProperties["cpMsg"] = "Pick the payroll month and year to pay this in.";
396	            return;
397	        }
398	
399	        int month = Convert.ToInt32(cmbMonth.Value);
400	        int year = Convert.ToInt32(spnYear.Number);
401	        int pushed;
402	
403	        using (SqlConnection conn = CreateConnection())
404	        {
405	            conn.Open();
406	
407	            // Re-checked server-side, not just in the banner: the callback is reachable from a
408	            // second tab whatever the screen is showing.
409	            // Verification first: it is the preparer's own sign-off, and a case that was never
410	            // calculated should be sent back rather than argued about parameter by parameter.
411	            string failing = ChecklistIncompleteReason(conn, "Verification", "verification");
412	            if (failing != null)
413	            {
414	                ApPanel.JSProperties["cpMsg"] = "Verification is incomplete: " + failing;
415	                return;
416	            }
417	
418	            failing = ChecklistIncompleteReason(conn, "ApprovalParameter", "approval parameter");
419	            if (failing != null)
420	            {
421	                ApPanel.JSProperties["cpMsg"] = "Approval parameter not passed: " + failing;
422	                return;
423	            }
424	
425	            using (SqlTransaction tx = conn.BeginTransaction())
426	            {
427	                try
428	                {
429	                    pushed = FNFSettlementService.ApproveCase(conn, tx, CurrentCaseId, month, year,
430	                                                              UserId, HostNameCapped());
431	                    tx.Commit();
432	                }
433	                catch
434	                {
435	                    try { tx.Rollback(); } catch { /* connection already gone */ }
436	                    throw;
437	                }
438	            }
439	        }
440	
441	        NotifyEmployee();
442	
443	        ApPanel.JSProperties["cpMsg"] = "Approved. " + pushed + " component(s) pushed into "
444	            + month.ToString("00") + "/" + year
445	            + ". Run Salary Generate for that month to pay it.";
446	        ApPanel.JSProperties["cpReloadList"] = true;
447	    }
448	
449	    /// <summary>
450	    /// Why a checklist is not complete, or null when it is.
451	    ///
452	    /// AN EMPTY CHECKLIST IS NOT A PASSED CHECKLIST. Asking only "is any required row
453	    /// failing" returns nothing when there are no rows at all, so a case whose verification
454	    /// was never seeded passed straight through - which is how FNF-2026-00002 got approved on
455	    /// two hand-typed settlement lines with Calculate never run.
456	    /// </summary>
457	    private string ChecklistIncompleteReason(SqlConnection conn, string kind, string label)
458	    {
459	        using (var cmd = new SqlCommand(@"
460	            SELECT COUNT(*) FROM dbo.HR_FNFCheck
461	            WHERE  FNFSettlementID = @Id AND CheckKind = @Kind", conn))
462	        {
463	            cmd.Parameters.AddWithValue("@Id", CurrentCaseId);
464	            cmd.Parameters.AddWithValue("@Kind", kind);
465	
466	            if (Convert.ToInt32(cmd.ExecuteScalar()) == 0)
467	                return "the " + label + " checklist is empty, so nothing has actually been "
468	                     + "checked. Send the case back to the preparer to run Calculate.";
469	        }
470	
471	        using (var cmd = new SqlCommand(@"
472	            SELECT TOP 1 CheckName + ' is ' + ISNULL(Result, 'not checked') + '.'
473	            FROM   dbo.HR_FNFCheck
474	            WHERE  FNFSettlementID = @Id AND CheckKind = @Kind
475	              AND  IsRequired = 1 AND ISNULL(Result, '') NOT IN ('Pass', 'NA')
476	            ORDER  BY SortOrder, FNFCheckID", conn))
477	        {
478	            cmd.Parameters.AddWithValue("@Id", CurrentCaseId);
479	            cmd.Parameters.AddWithValue("@Kind", kind);
480	            object value = cmd.ExecuteScalar();
481	            return (value == null || value == DBNull.Value) ? null : Convert.ToString(value);
482	        }
483	    }
484	
485	    private void HandleReject()
486	    {
487	        if (CurrentCaseId <= 0) return;
488	
489	        string reason = (memReject.Text ?? string.Empty).Trim();
490	        if (reason.Length == 0)
491	        {
492	            ApPanel.JSProperties["cpMsg"] = "Say why you are returning it - the preparer needs the reason.";
493	            return;
494	        }
495	
496	        using (SqlConnection conn = CreateConnection())
497	        {
498	            conn.Open();
499	            using (SqlTransaction tx = conn.BeginTransaction())
500	            {
501	                try
502	                {
503	                    FNFSettlementService.RejectCase(conn, tx, CurrentCaseId, UserId, reason);
504	                    tx.Commit();
505	                }
506	                catch { try { tx.Rollback(); } catch { } throw; }
507	            }
508	        }
509	
510	        ApPanel.JSProperties["cpMsg"] = "Returned to the preparer as a draft.";
511	        ApPanel.JSProperties["cpReloadList"] = true;
512	    }
