   162	    private void StampShared()
   163	    {
   164	        try
   165	        {
   166	            using (SqlConnection conn = CreateConnection())
   167	            using (var cmd = new SqlCommand(@"
   168	                UPDATE dbo.HR_FNFSettlement
   169	                SET    StatementSharedOn = GETDATE()
   170	                WHERE  FNFSettlementID = @Id AND StatementSharedOn IS NULL", conn))
   171	            {
   172	                cmd.Parameters.AddWithValue("@Id", CurrentCaseId);
   173	                conn.Open();
   174	                cmd.ExecuteNonQuery();
   175	            }
   176	        }
   177	        catch (Exception ex)
   178	        {
   179	            ErrorLogHelper.Log(ex, "MyFNFStatement.StampShared");
   180	        }
   181	    }
