   281	    private void HandleRespond(string result)
   282	    {
   283	        if (CurrentCaseId <= 0) return;
   284	
   285	        if (result != "Accepted" && result != "Accepted with Pending Query" && result != "Not Accepted")
   286	        {
   287	            StPanel.JSProperties["cpMsg"] = "That is not a valid response.";
   288	            return;
   289	        }
   290	
   291	        string remarks = (memRemarks.Text ?? string.Empty).Trim();
   292	        if (result != "Accepted" && remarks.Length == 0)
   293	        {
   294	            StPanel.JSProperties["cpMsg"] = "Please say what is wrong - HR needs the detail.";
   295	            return;
   296	        }
   297	
   298	        // Re-checked here, not just by hiding the buttons: the callback is reachable from a
   299	        // second tab, and a second response would overwrite the first silently.
   300	        using (SqlConnection conn = CreateConnection())
   301	        {
   302	            conn.Open();
   303	
   304	            using (var cmd = new SqlCommand(@"
   305	                SELECT ISNULL(AcceptanceResult, '') FROM dbo.HR_FNFSettlement
   306	                WHERE  FNFSettlementID = @Id AND EmployeeMasterID = @Emp AND Status = 1", conn))
   307	            {
   308	                cmd.Parameters.AddWithValue("@Id", CurrentCaseId);
   309	                cmd.Parameters.AddWithValue("@Emp", MyEmployeeId);
   310	                object existing = cmd.ExecuteScalar();
   311	
   312	                if (existing == null)
   313	                {
   314	                    // Not theirs, or gone. Same message either way - never confirm that
   315	                    // somebody else's settlement exists.
   316	                    StPanel.JSProperties["cpMsg"] = "That statement is not available.";
   317	                    return;
   318	                }
   319	                if (Convert.ToString(existing).Length > 0)
   320	                {
   321	                    StPanel.JSProperties["cpMsg"] = "You have already responded to this statement.";
   322	                    return;
   323	                }
   324	            }
   325	
   326	            using (SqlTransaction tx = conn.BeginTransaction())
   327	            {
   328	                try
   329	                {
   330	                    FNFSettlementService.RecordAcceptance(conn, tx, CurrentCaseId, result,
   331	                                                          remarks, UserId, HostNameCapped());
   332	                    tx.Commit();
   333	                }
   334	                catch { try { tx.Rollback(); } catch { } throw; }
   335	            }
   336	        }
   337	
   338	        NotifyHr(result, remarks);
   339	
   340	        LoadMyStatement();
   341	        StPanel.JSProperties["cpMsg"] = result == "Accepted"
   342	            ? "Thank you - your acceptance has been recorded."
   343	            : "Recorded. HR has been notified and will come back to you.";
   344	    }
