   346	    /// <summary>
   347	    /// Tells the people named on the case. Wrapped so a notification failure can never take
   348	    /// the employee's response down with it - their answer matters more than the alert.
   349	    /// </summary>
   350	    private void NotifyHr(string result, string remarks)
   351	    {
   352	        try
   353	        {
   354	            const string sql = @"
   355	                SELECT CaseNo,
   356	                       ISNULL(HRExecutiveUserMasterID, 0), ISNULL(PayrollExecutiveUserMasterID, 0),
   357	                       ISNULL(ApproverUserMasterID, 0), ISNULL(EntryUserMasterID, 0)
   358	                FROM   dbo.HR_FNFSettlement WHERE FNFSettlementID = @Id";
   359	
   360	            string caseNo = null;
   361	            var targets = new System.Collections.Generic.List<int>();
   362	
   363	            using (SqlConnection conn = CreateConnection())
   364	            using (var cmd = new SqlCommand(sql, conn))
   365	            {
   366	                cmd.Parameters.AddWithValue("@Id", CurrentCaseId);
   367	                conn.Open();
   368	                using (SqlDataReader rd = cmd.ExecuteReader())
   369	                {
   370	                    if (!rd.Read()) return;
   371	                    caseNo = rd.GetString(0);
   372	                    for (int i = 1; i <= 4; i++)
   373	                    {
   374	                        int uid = Convert.ToInt32(rd.GetValue(i));
   375	                        // Deduped, and the employee's own login excluded - they know what they
   376	                        // just did.
   377	                        if (uid > 0 && uid != UserId && !targets.Contains(uid)) targets.Add(uid);
   378	                    }
   379	                }
   380	            }
   381	
   382	            string title = "F&F " + caseNo + ": employee responded - " + result;
   383	            string body = string.IsNullOrEmpty(remarks)
   384	                ? "The employee accepted the settlement."
   385	                : "The employee said: " + remarks;
   386	
   387	            foreach (int uid in targets)
   388	                NotificationHelper.TrySend(uid, CompanyId, title, body, "Payroll",
   389	                                           MyEmployeeId, CurrentCaseId, "FNFSettlement");
   390	        }
   391	        catch (Exception ex)
   392	        {
   393	            ErrorLogHelper.Log(ex, "MyFNFStatement.Notify");
   394	        }
   395	    }
   396	}
