    61	    protected void StPanel_Callback(object sender, CallbackEventArgsBase e)
    62	    {
    63	        string[] parts = (e.Parameter ?? string.Empty).Split('|');
    64	        if (parts.Length < 2) return;
    65	
    66	        try
    67	        {
    68	            switch (parts[0])
    69	            {
    70	                case "Load":    LoadMyStatement(); break;
    71	                case "Respond": HandleRespond(parts.Length > 2 ? parts[2] : null); break;
    72	            }
    73	        }
    74	        catch (Exception ex)
    75	        {
    76	            ErrorLogHelper.Log(ex, "MyFNFStatement." + parts[0]);
    77	            StPanel.JSProperties["cpMsg"] = ErrorLogHelper.FriendlyMessage;
