    81	    private void LoadMyStatement()
    82	    {
    83	        CurrentCaseId = 0;
    84	        pnlStatement.Visible = false;
    85	        litSummary.Text = string.Empty;
    86	        StPanel.JSProperties["cpCanRespond"] = "0";
    87	
    88	        if (MyEmployeeId <= 0)
    89	        {
    90	            litBanner.Text =
    91	                "<div class=\"st-banner none\">This page shows your own settlement, and your login "
    92	              + "is not linked to an employee record - so there is nothing to show. An HR or admin "
    93	              + "login should use <b>Full &amp; Final Settlement</b> instead.</div>";
    94	            return;
    95	        }
    96	
    97	        // Scoped to the signed-in employee in the query itself, so nothing downstream can
    98	        // widen it. Only a decided settlement is shown: a draft is still being worked on and
    99	        // showing it would invite argument about figures that are going to change.
   100	        const string sql = @"
   101	            SELECT TOP 1 F.*,
   102	                   LTRIM(ISNULL(' ' + NULLIF(LTRIM(RTRIM(EM.FirstName)),''), '') + ISNULL(' ' + NULLIF(LTRIM(RTRIM(EM.FatherName)),''), '') + ISNULL(' ' + NULLIF(LTRIM(RTRIM(EM.LastName)),''), '')) AS EmployeeName,
   103	                   ISNULL(EM.Code, '') AS EmployeeCode
   104	            FROM   dbo.HR_FNFSettlement F
   105	            LEFT   JOIN dbo.HR_EmployeeMaster EM ON EM.EmployeeMasterID = F.EmployeeMasterID
   106	            WHERE  F.EmployeeMasterID = @Emp
   107	              AND  F.Status = 1
   108	              AND  F.WorkflowStatus IN (@Approved, @Paid)
   109	            ORDER  BY F.FNFSettlementID DESC";
   110	
   111	        DataRow row = null;
   112	        try
   113	        {
   114	            using (SqlConnection conn = CreateConnection())
   115	            using (var cmd = new SqlCommand(sql, conn))
   116	            {
   117	                cmd.Parameters.AddWithValue("@Emp", MyEmployeeId);
   118	                cmd.Parameters.AddWithValue("@Approved", FNFCaseService.StatusApproved);
   119	                cmd.Parameters.AddWithValue("@Paid", FNFCaseService.StatusPaid);
   120	                var dt = new DataTable();
   121	                using (var da = new SqlDataAdapter(cmd)) da.Fill(dt);
   122	                if (dt.Rows.Count > 0) row = dt.Rows[0];
   123	            }
   124	        }
   125	        catch (Exception ex)
   126	        {
   127	            ErrorLogHelper.Log(ex, "MyFNFStatement.Load");
   128	            litBanner.Text = "<div class=\"st-banner none\">" + HttpUtility.HtmlEncode(ErrorLogHelper.FriendlyMessage) + "</div>";
   129	            return;
   130	        }
   131	
   132	        if (row == null)
   133	        {
   134	            litBanner.Text =
   135	                "<div class=\"st-banner none\">You have no approved settlement to review. A "
   136	              + "statement appears here once HR has calculated it and it has been approved.</div>";
   137	            return;
   138	        }
   139	
   140	        CurrentCaseId = Convert.ToInt64(row["FNFSettlementID"]);
   141	        pnlStatement.Visible = true;
   142	
   143	        string response = Convert.ToString(row["AcceptanceResult"]);
   144	        bool alreadyResponded = !string.IsNullOrEmpty(response);
   145	
   146	        memRemarks.Text = Convert.ToString(row["AcceptanceRemarks"]);
   147	        memRemarks.ClientEnabled = !alreadyResponded;
   148	
   149	        litSummary.Text = BuildSummaryHtml(row);
   150	        litBanner.Text = BuildBannerHtml(row, response, alreadyResponded);
   151	
   152	        LineGrid.DataBind();
   153	
   154	        // Respond once. A second response would overwrite the first with no record of it,
   155	        // and this is the one field an ex-employee's dispute rests on.
   156	        StPanel.JSProperties["cpCanRespond"] = alreadyResponded ? "0" : "1";
   157	
   158	        // Seeing the statement IS the sharing event, so stamp it the first time.
   159	        if (row["StatementSharedOn"] == DBNull.Value) StampShared();
   160	    }
