   192	    private string BuildSummaryHtml(DataRow row)
   193	    {
   194	        decimal net = row["NetPayable"] == DBNull.Value ? 0m : Convert.ToDecimal(row["NetPayable"]);
   195	        string netLabel = net < 0 ? "Recoverable from you" : "Net Payable to you";
   196	        string netClass = net < 0 ? "st-net neg" : "st-net";
   197	
   198	        var sb = new System.Text.StringBuilder();
   199	        sb.Append("<table class=\"st-kv\" style=\"border-collapse:collapse\"><tr>");
   200	        sb.Append(Cell("Statement No.", row["CaseNo"]));
   201	        sb.Append(Cell("Name", row["EmployeeName"]));
   202	        sb.Append(Cell("Employee Code", row["EmployeeCode"]));
   203	        sb.Append(Cell("Last Working Day", row["LastWorkingDate"] == DBNull.Value
   204	            ? null : (object)Convert.ToDateTime(row["LastWorkingDate"]).ToString("dd-MM-yyyy")));
   205	        sb.Append("</tr><tr>");
   206	        sb.Append(Cell("Total Paid", Convert.ToDecimal(row["TotalEarnings"] == DBNull.Value ? 0m : row["TotalEarnings"]).ToString("n2")));
   207	        sb.Append(Cell("Total Deducted", Convert.ToDecimal(row["TotalDeductions"] == DBNull.Value ? 0m : row["TotalDeductions"]).ToString("n2")));
   208	        sb.Append("<td style=\"padding:4px 18px 4px 0;white-space:nowrap\"><span style=\"color:#777\">")
   209	          .Append(HttpUtility.HtmlEncode(netLabel)).Append("</span><br /><span class=\"")
   210	          .Append(netClass).Append("\">").Append(Math.Abs(net).ToString("n2")).Append("</span></td>");
   211	        sb.Append(Cell("Query window closes", row["ComplianceWindowEnd"] == DBNull.Value
   212	            ? null : (object)Convert.ToDateTime(row["ComplianceWindowEnd"]).ToString("dd-MM-yyyy")));
   213	        sb.Append("</tr></table>");
   214	        return sb.ToString();
   215	    }
