   217	    private string BuildBannerHtml(DataRow row, string response, bool alreadyResponded)
   218	    {
   219	        if (alreadyResponded)
   220	        {
   221	            string when = row["AcceptedOn"] == DBNull.Value
   222	                ? string.Empty
   223	                : " on " + Convert.ToDateTime(row["AcceptedOn"]).ToString("dd-MM-yyyy");
   224	
   225	            string cls = string.Equals(response, "Accepted", StringComparison.OrdinalIgnoreCase)
