   228	            return "<div class=\"st-banner " + cls + "\">You recorded: <b>"
   229	                 + HttpUtility.HtmlEncode(response) + "</b>" + when
   230	                 + ". HR can see your remarks. If something still needs sorting out, contact HR "
   231	                 + "directly - the query window date is shown below.</div>";
   232	        }
   233	
   234	        return "<div class=\"st-banner wait\">Please review the figures below and record your "
   235	             + "response. Nothing is paid out differently because of your answer - it records "
   236	             + "whether you agree, and anything you disagree with goes to HR.</div>";
