        public string GratuityBase;              // Basic | Basic+DA | Gross
        public string PerDayRateBase;            // Basic | Gross | CTC
        public string PerDayRateDivisorType;     // Fixed | MonthDays | WorkingDays
        public decimal PerDayRateDivisorValue;
