827	                           AmountOf(result, CompGratuity).ToString("n2"), 1 },
828	            new object[] { "AP_ENCASH", "Leave encashment days", encashPolicy,
829	                           encashDays.ToString("0.##") + " days", 2 },
830	            new object[] { "AP_NOTICE", "Notice pay recovery", "As per notice policy",
831	                           AmountOf(result, CompNoticeRecovery).ToString("n2"), 3 },
832	            new object[] { "AP_RECOVERY", "Total recoveries", "Must match clearance dues",
833	                           result.TotalDeductions.ToString("n2"), 4 },
834	            new object[] { "AP_NET", "Net payable", "-", result.NetPayable.ToString("n2"), 5 },
835	        };
836	
837	        foreach (object[] r in rows)
838	        {
839	            using (var cmd = new SqlCommand(@"
840	                UPDATE dbo.HR_FNFCheck
841	                SET    PolicyStandard = @Policy, ActualValue = @Actual
842	                WHERE  FNFSettlementID = @Id AND CheckKind = 'ApprovalParameter' AND CheckCode = @Code;
843	
844	                IF @@ROWCOUNT = 0
845	                    INSERT INTO dbo.HR_FNFCheck
846	                        (FNFSettlementID, CheckKind, CheckCode, CheckName, IsRequired,
847	                         PolicyStandard, ActualValue, SortOrder)
848	                    VALUES (@Id, 'ApprovalParameter', @Code, @Name, 1, @Policy, @Actual, @Sort);", conn, tx))
849	            {
850	                cmd.Parameters.AddWithValue("@Id", caseId);
851	                cmd.Parameters.AddWithValue("@Code", Convert.ToString(r[0]));
852	                cmd.Parameters.AddWithValue("@Name", Convert.ToString(r[1]));
853	                cmd.Parameters.AddWithValue("@Policy", Convert.ToString(r[2]));
854	                cmd.Parameters.AddWithValue("@Actual", Convert.ToString(r[3]));
855	                cmd.Parameters.AddWithValue("@Sort", Convert.ToInt32(r[4]));
856	                cmd.ExecuteNonQuery();
