861	    /// <summary>
862	    /// Approves a settlement and does everything that follows from it, in one transaction:
863	    /// stamps the status, settlement date and compliance window, pushes the money into the
864	    /// chosen payroll month, and settles the loan schedule it recovered.
865	    ///
866	    /// Refuses a case that is not Submitted, so a second approver pressing the button cannot
867	    /// approve it twice and push the money twice.
868	    ///
869	    /// Returns how many components reached payroll.
870	    /// </summary>
871	    public static int ApproveCase(SqlConnection conn, SqlTransaction tx, long caseId,
872	                                  int month, int year, int userId, string systemName)
873	    {
874	        string status;
875	        int windowDays;
876	
877	        using (var cmd = new SqlCommand(@"
878	            SELECT F.WorkflowStatus, ISNULL(C.ComplianceWindowDays, ISNULL(F.ComplianceWindowDays, 90))
879	            FROM   dbo.HR_FNFSettlement F
880	            LEFT   JOIN dbo.HR_FNFConfig C ON C.CompanyMasterID = F.CompanyMasterID AND C.Status = 1
881	            WHERE  F.FNFSettlementID = @Id AND F.Status = 1", conn, tx))
882	        {
883	            cmd.Parameters.AddWithValue("@Id", caseId);
884	            using (SqlDataReader rd = cmd.ExecuteReader())
885	            {
886	                if (!rd.Read())
887	                    throw new InvalidOperationException("F&F case " + caseId + " was not found.");
888	                status = rd.GetString(0);
889	                windowDays = Convert.ToInt32(rd.GetValue(1));
890	            }
891	        }
892	
893	        if (!string.Equals(status, FNFCaseService.StatusSubmitted, StringComparison.OrdinalIgnoreCase))
894	            throw new InvalidOperationException(
895	                "This case is " + status + ", not Submitted, so it cannot be approved. " +
896	                "Only a submitted settlement can be signed off.");
897	
898	        using (var cmd = new SqlCommand(@"
899	            UPDATE dbo.HR_FNFSettlement
900	            SET    WorkflowStatus        = @Approved,
901	                   SettlementDate        = CAST(GETDATE() AS date),
902	                   ComplianceWindowDays  = @WindowDays,
903	                   ComplianceWindowStart = CAST(GETDATE() AS date),
904	                   ComplianceWindowEnd   = DATEADD(DAY, @WindowDays, CAST(GETDATE() AS date)),
905	                   ApproverUserMasterID  = ISNULL(ApproverUserMasterID, @UserID),
906	                   EditUserMasterID      = @UserID,
907	                   EditUserDateTime      = GETDATE()
908	            WHERE  FNFSettlementID = @Id AND WorkflowStatus = @Submitted", conn, tx))
909	        {
910	            cmd.Parameters.AddWithValue("@Approved", FNFCaseService.StatusApproved);
911	            cmd.Parameters.AddWithValue("@Submitted", FNFCaseService.StatusSubmitted);
912	            cmd.Parameters.AddWithValue("@WindowDays", windowDays);
913	            cmd.Parameters.AddWithValue("@UserID", userId);
914	            cmd.Parameters.AddWithValue("@Id", caseId);
915	
916	            if (cmd.ExecuteNonQuery() == 0)
917	                throw new InvalidOperationException(
918	                    "Somebody else changed this case a moment ago. Re-open it and try again.");
919	        }
920	
921	        int pushed = PushToPayroll(conn, tx, caseId, month, year, userId, systemName);
922	        SettleLoanSchedule(conn, tx, caseId);
923	        return pushed;
924	    }
