1009	    /// <summary>
1010	    /// Writes one HR_SalaryAdditionalHead row per pushable component for the settlement
1011	    /// month, so the next Salary Generate for that month carries the settlement.
1012	    ///
1013	    /// Returns the number of components pushed. Throws with a message naming the component
1014	    /// when a head is not configured, rather than silently dropping money.
1015	    /// </summary>
1016	    public static int PushToPayroll(SqlConnection conn, SqlTransaction tx, long caseId,
1017	                                    int month, int year, int userId, string systemName)
1018	    {
1019	        DataRow head = LoadCaseRow(conn, tx, caseId);
1020	        if (head == null) throw new InvalidOperationException("F&F case " + caseId + " was not found.");
1021	
1022	        long employeeId = Convert.ToInt64(head["EmployeeMasterID"]);
1023	        long companyId = Convert.ToInt64(head["CompanyMasterID"]);
1024	        long categoryId = head["CategoryMasterID"] == DBNull.Value ? 0 : Convert.ToInt64(head["CategoryMasterID"]);
1025	        long branchId = head["BranchMasterID"] == DBNull.Value ? 0 : Convert.ToInt64(head["BranchMasterID"]);
1026	
1027	        // Needed for the head fallback below: a MANUALLY added detail row carries no
1028	        // SalaryHeadMasterID, because the person typing an extra line should not have to
1029	        // know which head pays it. Its component type is enough to resolve one.
1030	        Config cfg = LoadConfig(conn, tx, companyId);
1031	
1032	        // The override joins on Category and Branch too, so a stale value silently matches
1033	        // nothing. Take them from the employee as they are NOW.
1034	        using (var cmd = new SqlCommand(
1035	            "SELECT CategoryMasterID, BranchMasterID FROM dbo.HR_EmployeeMaster WHERE EmployeeMasterID = @Emp",
1036	            conn, tx))
1037	        {
1038	            cmd.Parameters.AddWithValue("@Emp", employeeId);
1039	            using (SqlDataReader rd = cmd.ExecuteReader())
1040	            {
1041	                if (rd.Read())
1042	                {
1043	                    if (!rd.IsDBNull(0)) categoryId = rd.GetInt64(0);
1044	                    if (!rd.IsDBNull(1)) branchId = rd.GetInt64(1);
1045	                }
1046	            }
1047	        }
1048	
1049	        var lines = new List<object[]>();
1050	        using (var cmd = new SqlCommand(@"
1051	            SELECT ComponentType, SalaryHeadMasterID, [Add/Deduct], SUM(Amount) AS Amount
1052	            FROM   dbo.HR_FNFSettlementDetail
1053	            WHERE  FNFSettlementID = @Id AND Amount <> 0
1054	            GROUP  BY ComponentType, SalaryHeadMasterID, [Add/Deduct]", conn, tx))
1055	        {
1056	            cmd.Parameters.AddWithValue("@Id", caseId);
1057	            using (SqlDataReader rd = cmd.ExecuteReader())
1058	                while (rd.Read())
1059	                    lines.Add(new object[]
1060	                    {
1061	                        rd.GetString(0),
1062	                        rd.IsDBNull(1) ? (long?)null : rd.GetInt64(1),
1063	                        rd.GetString(2),
1064	                        rd.GetDecimal(3),
1065	                    });
1066	        }
1067	
1068	        int pushed = 0;
1069	
1070	        foreach (object[] line in lines)
1071	        {
1072	            string component = Convert.ToString(line[0]);
1073	            if (!IsPushable(component)) continue;      // payroll already pays the final salary
1074	
1075	            // The row's own head wins; a manual row falls back to the one configured for
1076	            // its component type.
1077	            long? headId = (long?)line[1] ?? cfg.HeadFor(component);
1078	            string addDeduct = Convert.ToString(line[2]);
1079	            decimal amount = Convert.ToDecimal(line[3]);
1080	
1081	            if (!headId.HasValue)
1082	                throw new InvalidOperationException(
1083	                    "No salary head is configured for " + component + ", so it cannot be paid. " +
1084	                    "Set it in F&F Configuration.");
1085	
1086	            // The override is only a LEFT JOIN onto HR_EmployeeWiseSalaryHead, so without a
1087	            // row there the amount is never seen - with no error at all.
1088	            EnsureEmployeeHead(conn, tx, employeeId, headId.Value, addDeduct,
1089	                               categoryId, branchId, companyId, userId, systemName);
1090	
1091	            UpsertAdditionalHead(conn, tx, employeeId, headId.Value, amount, month, year,
1092	                                 categoryId, branchId, component, userId, systemName);
1093	            pushed++;
1094	        }
1095	
1096	        using (var cmd = new SqlCommand(@"
1097	            UPDATE dbo.HR_FNFSettlement
1098	            SET    SettlementMonth = @M, SettlementYear = @Y,
1099	                   EditUserMasterID = @UserID, EditUserDateTime = GETDATE()
1100	            WHERE  FNFSettlementID = @Id", conn, tx))
1101	        {
1102	            cmd.Parameters.AddWithValue("@M", month);
1103	            cmd.Parameters.AddWithValue("@Y", year);
1104	            cmd.Parameters.AddWithValue("@UserID", userId);
1105	            cmd.Parameters.AddWithValue("@Id", caseId);
1106	            cmd.ExecuteNonQuery();
1107	        }
1108	
1109	        return pushed;
1110	    }
