1112	    /// <summary>
1113	    /// Makes sure the employee's own salary structure carries this head, at Amount 0 and
1114	    /// AmountCalculation = 'Manual'.
1115	    ///
1116	    /// Amount stays 0 because that row is the STANDING structure — a figure written there
1117	    /// would be deducted or paid every month forever. The settlement amount goes in the
1118	    /// per-month override instead, exactly as a loan installment does.
1119	    ///
1120	    /// 'Manual' is load-bearing: IsFixedAmountType() exempts only 'Manual' and
1121	    /// 'FixPerMonthDay' from pro-rata, so on any other type CalculateHeads() would scale
1122	    /// the settlement by TotalPayDays / MonthDays.
1123	    /// </summary>
1124	    private static void EnsureEmployeeHead(SqlConnection conn, SqlTransaction tx, long employeeId,
1125	                                            long headId, string addDeduct, long categoryId,
1126	                                            long branchId, long companyId, int userId, string systemName)
1127	    {
1128	        using (var cmd = new SqlCommand(@"
1129	            IF NOT EXISTS (SELECT 1 FROM dbo.HR_EmployeeWiseSalaryHead
1130	                           WHERE EmployeeMasterID = @Emp AND SalaryHeadMasterID = @Head
1131	                             AND CategoryMasterID = @Cat AND BranchMasterID = @Br)
1132	            BEGIN
1133	                INSERT INTO dbo.HR_EmployeeWiseSalaryHead
1134	                    ([Sr.No.], CheckBox, SalaryHeadMasterID, AccountHeadCode, [Add/Deduct],
1135	                     Percentage, Amount, AmountCalculation, Formula, RoundOff, AllowEdit,
1136	                     Remarks, EmployeeMasterID, CategoryMasterID, BranchMasterID, CompanyMasterID, Status)
1137	                SELECT ISNULL((SELECT MAX([Sr.No.]) FROM dbo.HR_EmployeeWiseSalaryHead
1138	                               WHERE EmployeeMasterID = @Emp), 0) + 1,
1139	                       1, @Head, ISNULL(SH.Code, ''), @AddDeduct,
1140	                       0, 0, 'Manual', '', 0, 0,
1141	                       'Added for F&F settlement', @Emp, @Cat, @Br, @Company, 1
1142	                FROM   dbo.HR_SalaryHeadMaster SH
1143	                WHERE  SH.SalaryHeadMasterID = @Head;
1144	            END", conn, tx))
1145	        {
1146	            cmd.Parameters.AddWithValue("@Emp", employeeId);
1147	            cmd.Parameters.AddWithValue("@Head", headId);
1148	            cmd.Parameters.AddWithValue("@AddDeduct", addDeduct);
1149	            cmd.Parameters.AddWithValue("@Cat", categoryId);
1150	            cmd.Parameters.AddWithValue("@Br", branchId);
1151	            cmd.Parameters.AddWithValue("@Company", companyId);
1152	            cmd.ExecuteNonQuery();
1153	        }
1154	    }
