1213	              AND  S.IsPaid = 0
1214	              AND  S.Status = 1
1215	              AND  EXISTS (SELECT 1 FROM dbo.HR_FNFSettlementDetail D
1216	                           WHERE D.FNFSettlementID = @Id
1217	                             AND D.ComponentType = @Comp
1218	                             AND D.Amount > 0)", conn, tx))
1219	        {
1220	            cmd.Parameters.AddWithValue("@Id", caseId);
1221	            cmd.Parameters.AddWithValue("@Comp", CompLoanRecovery);
