    /// where none existed before (see the class remarks: today's ApproveAsync/RejectAsync have zero
    /// decision-level auth beyond [Authorize] + company scoping). Returns null to proceed with the
    /// legacy write, or the (status, message) to refuse the request with.
    /// </summary>
    private async Task<(HttpStatusCode Status, string Message)?> ApplyApprovalEngineGateAsync(long caseId, string decision, string? remarks)
    {
        var formDocId = await _approvalService.ResolveFormDocIdAsync(ApprovalModuleKeys.Fnf, FnfFormDocNames.Approval);
        var instanceId = formDocId is null ? null : await _approvalService.GetInstanceIdAsync(formDocId.Value, caseId);
        if (instanceId is null) return null;

        var actionResult = await _approvalService.Action(new ApprovalActionModel
        {
            ApprovalInstanceId = instanceId.Value,
            EmployeeId = _requestMetadata.EmployeeMasterId,
            Decision = decision,
            Remarks = remarks,
        });

        if (actionResult.IsSuccess) return null;

        if (actionResult.Status == HttpStatusCode.Conflict)
        {
            // Most likely a stale instance from a prior reject-then-resubmit cycle for this same
            // caseId (TryCreateApprovalInstanceAsync could not create a fresh one on resubmission -
            // HR_ApprovalInstance has no "reopen" concept, same precedent as Recruitment's Reopen
            // transitions bypassing the engine entirely). Not a real double-decision race: the
            // WorkflowStatus check the caller already ran, plus ApproveCaseHeaderAsync/
            // RejectCaseAsync's own `rows == 0` optimistic-concurrency guard, already catch two
            // people deciding the SAME live pending case - so falling through here instead of
            // hard-blocking is safe.
            _logger.LogInformation(
                "F&F case {CaseId}: approval engine instance already closed (likely stale from a prior reject/resubmit cycle) - falling through to the existing WorkflowStatus check.",
                caseId);
            return null;
        }

        return (actionResult.Status, actionResult.Message);
    }

    /// <summary>
    /// Config mode note: there is no existing rule to preserve here (see the class remarks) - this
    /// is genuinely new authorization, not a translation of one. HR_FNFSettlement already carries
    /// per-case HrExecutiveUserMasterId/PayrollExecutiveUserMasterId/FinanceExecutiveUserMasterId/
    /// ApproverUserMasterId planning fields, but they are UserMasterIds (not EmployeeMasterIds) and
    /// are purely informational today - nothing reads them for authorization, and wiring them into
    /// the engine would need a UserMasterId -> EmployeeMasterId resolution this migration does not
    /// add. Expected initial setup: `any_one` with the actual Finance/HR/Payroll employee(s) who
    /// sign off F&amp;F cases configured explicitly as HR_ApprovalConfigApprover rows - or
    /// `default_chain` (IsReportingMgrRequired=true) if the policy is "the exiting employee's
    /// manager approves it" instead (HR_FNFSettlement.ReportingPersonId is available for this).
    /// Which is correct is a real policy decision, not something inferable from legacy code, since
    /// none existed.
    /// </summary>
    private async Task TryCreateApprovalInstanceAsync(long caseId, long requestorEmployeeId, long companyMasterId)
    {
        try
        {
            var formDocId = await _approvalService.ResolveFormDocIdAsync(ApprovalModuleKeys.Fnf, FnfFormDocNames.Approval);
            if (formDocId is null)
            {
                _logger.LogWarning("No 'FNF Approval' FormDocMaster row found - skipping approval instance creation for F&F case {CaseId}", caseId);
                return;
            }

            var result = await _approvalService.CreateInstance(new CreateApprovalInstanceModel
            {
                FormDocId = formDocId.Value,
                TransactionRecordId = caseId,
                RequestorEmployeeId = requestorEmployeeId,
                CompanyMasterId = companyMasterId,
                BranchMasterId = null,
            });

            if (!result.IsSuccess || result.Data == null)
                _logger.LogWarning("Could not create approval instance for F&F case {CaseId}: {Message}", caseId, result.Message);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Unexpected error creating approval instance for F&F case {CaseId}", caseId);
        }
    }

    private static ResponseModel Success(ResponseModel res, string message, object? data = null)
    {
        res.IsSuccess = true; res.Status = HttpStatusCode.OK; res.Message = message; res.Data = data;
        return res;
    }

    private static ResponseModel Fail(ResponseModel res, HttpStatusCode status, string message)
    {
        res.IsSuccess = false; res.Status = status; res.Message = message;
        return res;
    }
}

