    public async Task SeedApprovalParametersAsync(long caseId, long companyMasterId)
    {
        var result = await CalculateAsync(caseId, companyMasterId, persist: false);
        var config = await LoadConfigAsync(companyMasterId);

        var gratuityPolicy = config.GratuityEnabled
            ? $"{config.GratuityEligibleYears:0.##} years, {config.GratuityDaysPerYear:0.##} days/yr on {config.GratuityBase}, /{config.GratuityDivisor:0.##}"
            : "switched off";
        var encashPolicy = config.EncashmentCapDays.HasValue ? $"capped at {config.EncashmentCapDays:0.##} days" : "no cap configured";
        var loanRecovery = result.Components.Where(c => c.ComponentType == "LoanRecovery").Sum(c => c.Amount);
        var totalRecoveries = result.Components.Where(c => c.ComponentType is "LoanRecovery" or "AssetRecovery" or "OtherRecovery").Sum(c => c.Amount);

        // Each row carries its own display name. The code was previously passed for both, so the
        // approver's checklist read "AP_GRATUITY" / "AP_ENCASH" - the internal keys - rather than
        // saying what was being confirmed.
        var rows = new[]
        {
            ("AP_GRATUITY", "Gratuity amount", gratuityPolicy, result.GratuityAmount),
            ("AP_ENCASH",   "Leave encashment amount", encashPolicy, result.LeaveEncashAmount),
            ("AP_NOTICE",   "Notice-period recovery", (string?)null,
                result.Components.Where(c => c.ComponentType == "NoticeRecovery").Sum(c => c.Amount)),
            ("AP_RECOVERY", "Total recoveries", null, totalRecoveries),
            ("AP_NET",      "Net payable", null, result.NetPayable),
        };
        var sortOrder = 10;
        foreach (var (code, name, policy, value) in rows)
        {
            await _repository.UpsertCheckAsync(caseId, "ApprovalParameter", code, name, isRequired: true,
                policyStandard: policy, actualValue: value.ToString("0.00"), sortOrder);
            sortOrder += 10;
        }
    }

    public async Task<int> PushToPayrollAsync(long caseId, long employeeMasterId, long companyMasterId, int month, int year)
    {
        var config = await LoadConfigAsync(companyMasterId);
        var current = await _repository.GetCurrentCategoryBranchAsync(employeeMasterId);
        var categoryMasterId = current?.CategoryMasterId ?? 0;
        var branchMasterId = current?.BranchMasterId ?? 0;

        var details = await _repository.GetSettlementDetailsAsync(caseId);
        var grouped = details
            .Where(d => IsPushable(d.ComponentType) && d.Amount != 0)
            .GroupBy(d => (d.ComponentType, d.SalaryHeadMasterId, d.AddDeduct))
            .Select(g => new { g.Key.ComponentType, g.Key.SalaryHeadMasterId, g.Key.AddDeduct, Amount = g.Sum(x => x.Amount) });

        var pushed = 0;
        foreach (var group in grouped)
        {
            var headId = group.SalaryHeadMasterId ?? HeadFor(group.ComponentType, config)
                ?? throw new InvalidOperationException($"No salary head configured for {group.ComponentType} - set it in F&F Configuration.");

            await _repository.EnsureEmployeeHeadAsync(employeeMasterId, headId, categoryMasterId, branchMasterId, companyMasterId);
            await _repository.UpsertAdditionalHeadAsync(employeeMasterId, headId, group.Amount, $"F&F settlement - {group.ComponentType}",
                month, year, categoryMasterId, branchMasterId);
            pushed++;
        }

        await _repository.StampSettlementMonthYearAsync(caseId, month, year);
        return pushed;
    }

    public async Task SettleLoanScheduleAsync(long caseId, long employeeMasterId)
    {
        var details = await _repository.GetSettlementDetailsAsync(caseId);
        if (details.Any(d => d.ComponentType == "LoanRecovery" && d.Amount > 0))
            await _repository.MarkLoanScheduleSettledAsync(employeeMasterId);
    }

    public async Task RecordAcceptanceAsync(long caseId, long employeeMasterId, long companyMasterId,
        string acceptanceResult, string? remarks, long userId)
    {
        await _repository.RecordAcceptanceAsync(caseId, acceptanceResult, remarks);

        // Reuses guide 02's own guard - never a second, duplicate check. Exit Formality is a
        // separate module this port does not build (05_FNFSettlementApproval.md §2) - reason/
        // feedback are left null here rather than reading a table that may not exist yet.
        if (!await _alumniRepository.HasLiveRecordAsync(employeeMasterId, excludeAlumniId: 0))
        {
            await _alumniRepository.AddFromSettlementAsync(employeeMasterId, caseId,
                reasonForLeaving: null, managerFeedback: null, userId, companyMasterId);
        }
    }

    public async Task<string?> ChecklistIncompleteReasonAsync(long caseId, string checkKind, string label)
    {
        var total = await _repository.CountChecksAsync(caseId, checkKind);
        if (total == 0)
            return $"the {label} checklist is empty, so nothing has actually been checked. Send the case back to the preparer to run Calculate.";

        var firstFailing = await _repository.GetFirstIncompleteRequiredCheckAsync(caseId, checkKind);
        return firstFailing == null ? null : $"{firstFailing.Value.CheckName} is {firstFailing.Value.Result ?? "not checked"}.";
    }
