        await _repository.RecordAcceptanceAsync(caseId, acceptanceResult, remarks);

        // Reuses guide 02's own guard - never a second, duplicate check. Exit Formality is a
        // separate module this port does not build (05_FNFSettlementApproval.md §2) - reason/
        // feedback are left null here rather than reading a table that may not exist yet.
        if (!await _alumniRepository.HasLiveRecordAsync(employeeMasterId, excludeAlumniId: 0))
        {
            await _alumniRepository.AddFromSettlementAsync(employeeMasterId, caseId,
                reasonForLeaving: null, managerFeedback: null, userId, companyMasterId);
        }
    }

    public async Task<string?> ChecklistIncompleteReasonAsync(long caseId, string checkKind, string label)
    {
        var total = await _repository.CountChecksAsync(caseId, checkKind);
        if (total == 0)
            return $"the {label} checklist is empty, so nothing has actually been checked. Send the case back to the preparer to run Calculate.";

        var firstFailing = await _repository.GetFirstIncompleteRequiredCheckAsync(caseId, checkKind);
        return firstFailing == null ? null : $"{firstFailing.Value.CheckName} is {firstFailing.Value.Result ?? "not checked"}.";
    }
