                     @EmployeeMasterId, @CategoryMasterId, @BranchMasterId, @CompanyMasterId, 1)";

            await _repo.ExecuteAsync(sql, new
            {
                EmployeeMasterId = employeeMasterId, HeadId = headId, CategoryMasterId = categoryMasterId,
                BranchMasterId = branchMasterId, CompanyMasterId = companyMasterId,
            });
            await _tx.CommitAsync();
        }
        catch { await _tx.RollbackAsync(); throw; }
    }

    public async Task UpsertAdditionalHeadAsync(long employeeMasterId, long headId, decimal amount, string remarks,
        int month, int year, long categoryMasterId, long branchMasterId)
    {
        await _tx.BeginTransactionAsync();
        try
        {
            const string sql = @"
                MERGE HR_SalaryAdditionalHead AS target
                USING (SELECT @EmployeeMasterId AS EmployeeMasterID, @HeadId AS SalaryHeadMasterID,
                              @Month AS AttendMonth, @Year AS AttendYear,
                              @CategoryMasterId AS CategoryMasterID, @BranchMasterId AS BranchMasterID) AS src
                  ON  target.EmployeeMasterID = src.EmployeeMasterID AND target.SalaryHeadMasterID = src.SalaryHeadMasterID
                  AND target.AttendMonth = src.AttendMonth AND target.AttendYear = src.AttendYear
                  AND target.CategoryMasterID = src.CategoryMasterID AND target.BranchMasterID = src.BranchMasterID
                WHEN MATCHED THEN
                    UPDATE SET Amount = @Amount, Remarks = @Remarks, EditUserMasterID = @UserId, EditUserDateTime = @Now
                WHEN NOT MATCHED THEN
                    INSERT (SalaryHeadMasterID, AccountHeadCode, EmployeeMasterID, Amount, Remarks, AttendMonth,
                            AttendYear, CategoryMasterID, BranchMasterID, EntryUserMasterID, EntryUserDateTime, SystemName)
                    VALUES (@HeadId, '', @EmployeeMasterId, @Amount, @Remarks, @Month, @Year,
                            @CategoryMasterId, @BranchMasterId, @UserId, @Now, @SystemName);";

            await _repo.ExecuteAsync(sql, new
            {
                EmployeeMasterId = employeeMasterId, HeadId = headId, Amount = amount, Remarks = remarks,
                Month = (decimal)month, Year = (decimal)year, CategoryMasterId = categoryMasterId,
                BranchMasterId = branchMasterId, UserId = 0L, Now = DateTime.Now, SystemName = "HRMS_WEB",
            });
            await _tx.CommitAsync();
        }
        catch { await _tx.RollbackAsync(); throw; }
    }

    public async Task<(long? CategoryMasterId, long? BranchMasterId)?> GetCurrentCategoryBranchAsync(long employeeMasterId)
    {
        const string sql = "SELECT CategoryMasterID, BranchMasterID FROM HR_EmployeeMaster WHERE EmployeeMasterID = @EmployeeMasterId";
        return await _repo.QueryFirstOrDefaultAsync<(long? CategoryMasterId, long? BranchMasterId)?>(sql, new { EmployeeMasterId = employeeMasterId });
    }
}

