               ISNULL(LTRIM(ISNULL(' ' + NULLIF(LTRIM(RTRIM(em.FirstName)),''), '')
                          + ISNULL(' ' + NULLIF(LTRIM(RTRIM(em.FatherName)),''), '')
                          + ISNULL(' ' + NULLIF(LTRIM(RTRIM(em.LastName)),''), '')), '') AS EmployeeName,
               ISNULL(em.Code, '') AS EmployeeCode,
