               f.PlannedCalcStartDate, f.PlannedSettlementDate, f.ActualCalcStartDate, f.ApprovalTurnaroundDays,
               f.HRExecutiveUserMasterID AS HrExecutiveUserMasterId,
               f.PayrollExecutiveUserMasterID AS PayrollExecutiveUserMasterId,
               f.FinanceExecutiveUserMasterID AS FinanceExecutiveUserMasterId,
               f.ApproverUserMasterID AS ApproverUserMasterId,
               f.NoticeDaysRequired, f.NoticeDaysServed,
               f.PerDayRate, f.PerDayRateBasis, f.LeaveEncashDays, f.LeaveEncashAmount, f.GratuityAmount,
               f.TotalEarnings, f.TotalDeductions, f.NetPayable,
               f.IsClearanceReady, f.ClearanceBlockReason,
               f.SettlementMonth, f.SettlementYear,
               f.AcceptanceResult, f.AcceptanceRemarks, f.AcceptedOn, f.StatementSharedOn,
               f.ComplianceWindowDays, f.ComplianceWindowStart, f.ComplianceWindowEnd,
               f.Remarks, f.CategoryMasterID AS CategoryMasterId, f.BranchMasterID AS BranchMasterId,
               f.CompanyMasterID AS CompanyMasterId
        FROM   HR_FNFSettlement f
        LEFT   JOIN HR_EmployeeMaster em ON em.EmployeeMasterID = f.EmployeeMasterID";

