  1	import { CommonModule } from '@angular/common';
  2	import { Component, OnInit } from '@angular/core';
  3	import { ActivatedRoute, Router } from '@angular/router';
  4	import { DxButtonModule, DxNumberBoxModule, DxPopupModule, DxSelectBoxModule, DxTextAreaModule } from 'devextreme-angular';
  5	import { finalize } from 'rxjs/operators';
  6	import { CommonGridComponent } from '../../../../layout/common-grid/common-grid.component';
  7	import { AuthService } from '../../../../services/auth.service';
  8	import { ChipNavigationService } from '../../../../services/ChipNavigation.service';
  9	import { ToastService } from '../../../../services/toaster.service';
 10	import { FnfCaseModel, FnfCheckModel, FnfSettlementDetailModel } from '../../models/fnf.model';
 11	import { FnfApiService } from '../../services/fnf-api.service';
 12	
 13	const MONTHS = [
 14	  { value: 1, text: 'January' }, { value: 2, text: 'February' }, { value: 3, text: 'March' },
 15	  { value: 4, text: 'April' }, { value: 5, text: 'May' }, { value: 6, text: 'June' },
