 89	          span.className = `status-pill ${cls}`;
 90	          span.innerText = result || 'Not answered';
 91	          container.appendChild(span);
 92	        },
 93	      },
 94	      { dataField: 'remarks', caption: 'Remarks' },
 95	    ];
 96	
 97	    this.load();
 98	  }
 99	
100	  load(): void {
101	    if (!this.caseId) return;
102	    this.loading = true;
103	    this.fnfApi
104	      .getApprovalCase(this.caseId)
105	      .pipe(finalize(() => (this.loading = false)))
106	      .subscribe({
107	        next: (res) => {
108	          if (!FnfApiService.isOk(res)) {
109	            this.toast.error(FnfApiService.messageOf(res, 'Failed to load case.'));
110	            return;
111	          }
112	          this.case = FnfApiService.dataOf<FnfCaseModel>(res);
113	          this.decisionMonth = this.case.settlementMonth;
114	          this.decisionYear = this.case.settlementYear ?? new Date().getFullYear();
115	        },
116	        error: (err) => this.toast.error(FnfApiService.errorMessage(err, 'Failed to load case.')),
117	      });
118	
119	    this.fnfApi.getSettlementDetails(this.caseId).subscribe({
120	      next: (res) => {
121	        const rows = FnfApiService.dataOf<FnfSettlementDetailModel[]>(res);
122	        this.settlementDetails = Array.isArray(rows) ? rows : [];
123	      },
124	    });
125	
126	    this.loadParameters();
127	  }
128	
129	  private loadParameters(): void {
130	    this.fnfApi.getApprovalParameters(this.caseId).subscribe({
131	      next: (res) => {
132	        const rows = FnfApiService.dataOf<FnfCheckModel[]>(res);
133	        this.parameters = Array.isArray(rows) ? [...rows].sort((a, b) => a.sortOrder - b.sortOrder) : [];
134	      },
135	    });
136	  }
137	
138	  goBack(): void {
139	    this.router.navigate(['/fnf/approval']);
140	  }
141	
142	  get isBlocked(): boolean {
143	    if (!this.case) return true;
144	    if (this.case.workflowStatus !== 'Submitted') return true;
145	    return this.parameters.some((p) => p.isRequired && p.result !== 'Pass' && p.result !== 'NA');
146	  }
147	
148	  approve(): void {
149	    if (!this.decisionMonth || !this.decisionYear) {
150	      this.toast.error('Choose the payroll month and year to pay this into.');
151	      return;
152	    }
153	    if (
154	      !confirm(
155	        'Approve this settlement? The amounts will be pushed into the selected payroll month and the loan schedule closed. This cannot be undone here.',
156	      )
157	    )
158	      return;
159	
160	    this.approveBusy = true;
161	    this.fnfApi
162	      .approveCase(this.caseId, { month: this.decisionMonth, year: this.decisionYear })
163	      .pipe(finalize(() => (this.approveBusy = false)))
164	      .subscribe({
165	        next: (res) => {
166	          if (!FnfApiService.isOk(res)) {
167	            this.toast.error(FnfApiService.messageOf(res, 'Approve failed.'));
168	            return;
169	          }
170	          this.toast.success(FnfApiService.messageOf(res, 'Approved.'));
171	          this.goBack();
172	        },
173	        // Interceptor toasts the reason (403/409 from the approval engine, etc.) — toasting
174	        // errorMessage() here too was double-showing the same message.
175	        error: () => {},
176	      });
177	  }
178	
179	  reject(): void {
180	    if (!this.rejectReason.trim()) {
181	      this.toast.error('Say why you are returning it — the preparer needs the reason.');
182	      return;
183	    }
184	    if (!confirm('Return this settlement to the preparer?')) return;
185	
186	    this.rejectBusy = true;
187	    this.fnfApi
188	      .rejectCase(this.caseId, { reason: this.rejectReason.trim() })
189	      .pipe(finalize(() => (this.rejectBusy = false)))
190	      .subscribe({
191	        next: (res) => {
192	          if (!FnfApiService.isOk(res)) {
193	            this.toast.error(FnfApiService.messageOf(res, 'Reject failed.'));
194	            return;
195	          }
196	          this.toast.success(FnfApiService.messageOf(res, 'Returned to the preparer as a draft.'));
197	          this.goBack();
198	        },
199	        // Interceptor toasts the reason (403/409 from the approval engine, etc.) — toasting
200	        // errorMessage() here too was double-showing the same message.
201	        error: () => {},
202	      });
203	  }
204	
205	  // ------------------------------------------------------------- Parameters
206	
207	  openParamEdit(row: FnfCheckModel): void {
208	    this.paramPopupRow = row;
209	    this.paramResult = row.result;
210	    this.paramRemarks = row.remarks ?? '';
211	    this.paramPopupVisible = true;
212	  }
213	
214	  saveParam(): void {
215	    if (!this.paramPopupRow) return;
216	    this.paramBusy = true;
217	    this.fnfApi
218	      .updateCheck(this.caseId, { fnfCheckId: this.paramPopupRow.fnfCheckId, result: this.paramResult, remarks: this.paramRemarks })
219	      .pipe(finalize(() => (this.paramBusy = false)))
220	      .subscribe({
221	        next: (res) => {
222	          if (!FnfApiService.isOk(res)) {
223	            this.toast.error(FnfApiService.messageOf(res, 'Could not update.'));
224	            return;
225	          }
226	          this.paramPopupVisible = false;
227	          this.loadParameters();
228	        },
229	        error: (err) => this.toast.error(FnfApiService.errorMessage(err, 'Could not update.')),
230	      });
231	  }
232	}

