  1	import { CommonModule } from '@angular/common';
  2	import { Component, OnInit } from '@angular/core';
  3	import { DxButtonModule, DxTextAreaModule } from 'devextreme-angular';
  4	import { finalize } from 'rxjs/operators';
  5	import { CommonGridComponent } from '../../../layout/common-grid/common-grid.component';
  6	import { AuthService } from '../../../services/auth.service';
  7	import { ChipNavigationService } from '../../../services/ChipNavigation.service';
  8	import { ToastService } from '../../../services/toaster.service';
  9	import { AcceptanceResult, FnfCaseModel, FnfSettlementDetailModel } from '../models/fnf.model';
 10	import { FnfApiService } from '../services/fnf-api.service';
 11	
 12	const COMPONENT_LABELS: Record<string, string> = {
 13	  FinalSalary: 'Final month salary',
 14	  LeaveEncashment: 'Leave encashment',
 15	  Gratuity: 'Gratuity',
 16	  NoticePay: 'Notice pay',
 17	  NoticeRecovery: 'Notice period recovery',
 18	  LoanRecovery: 'Loan / advance recovery',
 19	  AssetRecovery: 'Company property recovery',
 20	  OtherRecovery: 'Other recovery',
 21	};
 22	
 23	/**
 24	 * Employee-facing "I accept this statement" screen — shows the signed-in
 25	 * employee's own approved settlement and nothing else.
 26	 *
 27	 * The API contract has no dedicated "my case" lookup, so this reads
 28	 * `GetCases` (the same list the preparer screen uses) and picks the most
 29	 * recent Approved case belonging to the signed-in employee. If the backend
 30	 * scopes GetCases strictly to team members/admins, an ordinary employee who
 31	 * isn't on the case's team will see nothing here — worth verifying against
 32	 * the real API.
 33	 */
 34	@Component({
 35	  selector: 'app-fnf-my-statement',
 36	  standalone: true,
 37	  imports: [CommonModule, CommonGridComponent, DxTextAreaModule, DxButtonModule],
 38	  templateUrl: './my-statement.component.html',
 39	})
 40	export class FnfMyStatementComponent implements OnInit {
 41	  loading = false;
 42	  responding = false;
 43	  case: FnfCaseModel | null = null;
 44	  lines: FnfSettlementDetailModel[] = [];
 45	  columns: Record<string, unknown>[] = [];
 46	  remarks = '';
 47	
 48	  constructor(
 49	    private authService: AuthService,
 50	    private fnfApi: FnfApiService,
 51	    private toast: ToastService,
 52	    private chipService: ChipNavigationService,
 53	  ) {
 54	    this.authService.ScreenName = 'My Full & Final Statement';
 55	    this.chipService.addTab({ title: 'My F&F Statement', route: '/fnf/my-statement' });
 56	  }
 57	
 58	  ngOnInit(): void {
 59	    this.columns = [
 60	      {
 61	        dataField: 'componentType',
 62	        caption: 'Item',
 63	        cellTemplate: (container: HTMLElement, options: any) => {
 64	          container.innerText = COMPONENT_LABELS[options.data?.componentType] ?? options.data?.componentType ?? '';
 65	        },
 66	      },
 67	      {
 68	        dataField: 'addDeduct',
 69	        caption: 'Paid / Deducted',
 70	        width: 130,
 71	        cellTemplate: (container: HTMLElement, options: any) => {
 72	          container.innerText = options.data?.addDeduct === 'Add' ? 'Paid' : 'Deducted';
 73	        },
 74	      },
 75	      { dataField: 'days', caption: 'Days', dataType: 'number', width: 80 },
 76	      { dataField: 'rate', caption: 'Rate', dataType: 'number', format: { type: 'fixedPoint', precision: 2 }, width: 100 },
 77	      { dataField: 'amount', caption: 'Amount', dataType: 'number', format: { type: 'fixedPoint', precision: 2 }, width: 120 },
 78	      { dataField: 'remarks', caption: 'How It Was Worked Out' },
 79	    ];
 80	
 81	    this.load();
 82	  }
 83	
 84	  load(): void {
 85	    const myEmployeeId = this.authService.getEmployeeId();
 86	    if (!myEmployeeId) {
 87	      this.toast.error('Your login is not linked to an employee record, so there is nothing to show here.');
 88	      return;
 89	    }
 90	
 91	    this.loading = true;
 92	    // getMyStatement, not getCases: the server works out whose statement this is from the token
 93	    // and returns only that. The old call fetched every case in the company and narrowed it here,
 94	    // which showed the right thing on screen while leaving the rest one API call away.
 95	    this.fnfApi
 96	      .getMyStatement()
 97	      .pipe(finalize(() => (this.loading = false)))
 98	      .subscribe({
 99	        next: (res) => {
100	          if (!FnfApiService.isOk(res)) {
101	            this.toast.error(FnfApiService.messageOf(res, 'Failed to load your statement.'));
102	            return;
103	          }
104	          const rows = FnfApiService.dataOf<FnfCaseModel[]>(res) ?? [];
105	          const mine = Array.isArray(rows) ? rows : [];
106	          this.case = mine[0] ?? null;
107	          this.remarks = this.case?.acceptanceRemarks ?? '';
108	          if (this.case) this.loadLines(this.case.fnfSettlementId);
109	        },
110	        error: (err) => this.toast.error(FnfApiService.errorMessage(err, 'Failed to load your statement.')),
111	      });
112	  }
113	
114	  private loadLines(caseId: number): void {
115	    this.fnfApi.getSettlementDetails(caseId).subscribe({
116	      next: (res) => {
117	        const rows = FnfApiService.dataOf<FnfSettlementDetailModel[]>(res);
118	        this.lines = Array.isArray(rows) ? rows : [];
119	      },
120	    });
121	  }
122	
123	  get alreadyResponded(): boolean {
124	    return !!this.case?.acceptanceResult;
125	  }
126	
127	  respond(result: AcceptanceResult): void {
128	    if (!this.case) return;
129	    if (result !== 'Accepted' && !this.remarks.trim()) {
130	      this.toast.error('Please say what is wrong — HR needs the detail to look into it.');
131	      return;
132	    }
133	    const question = result === 'Accepted' ? 'Accept this settlement as correct?' : 'Send this response to HR?';
134	    if (!confirm(question)) return;
135	
136	    this.responding = true;
137	    this.fnfApi
138	      .acceptStatement(this.case.fnfSettlementId, { acceptanceResult: result, remarks: this.remarks.trim() || null })
139	      .pipe(finalize(() => (this.responding = false)))
140	      .subscribe({
141	        next: (res) => {
142	          if (!FnfApiService.isOk(res)) {
143	            this.toast.error(FnfApiService.messageOf(res, 'Could not record your response.'));
144	            return;
145	          }
146	          this.toast.success(
147	            result === 'Accepted' ? 'Thank you — your acceptance has been recorded.' : 'Recorded. HR has been notified and will come back to you.',
148	          );
149	          this.load();
150	        },
151	        error: (err) => this.toast.error(FnfApiService.errorMessage(err, 'Could not record your response.')),
152	      });
153	  }
154	}
  1	<div class="page-wrapper">
  2	  <div class="main-card main-card--page-shell">
  3	    <div class="page-header">
  4	      <div class="page-title">My Full &amp; Final Statement</div>
  5	      <dx-button icon="refresh" text="Refresh" stylingMode="outlined" [disabled]="loading" (onClick)="load()"></dx-button>
  6	    </div>
  7	    <hr class="divider" />
  8	    <div class="main-card-body">
  9	      @if (!case) {
 10	        <div class="popup-banner">
 11	          <p class="mb-0">You have no approved settlement to review yet. A statement appears here once HR has calculated it and it has been approved.</p>
 12	        </div>
 13	      } @else {
 14	        <div class="popup-banner mb-3" [class.ready]="alreadyResponded && case.acceptanceResult === 'Accepted'" [class.wait]="!alreadyResponded || case.acceptanceResult !== 'Accepted'">
 15	          @if (alreadyResponded) {
 16	            <p class="mb-0">
 17	              You recorded: <b>{{ case.acceptanceResult }}</b>
 18	              @if (case.acceptedOn) { on {{ case.acceptedOn | date: 'dd-MMM-yyyy' }} }
 19	              . HR can see your remarks. If something still needs sorting out, contact HR directly
 20	              @if (case.complianceWindowEnd) { — the query window closes {{ case.complianceWindowEnd | date: 'dd-MMM-yyyy' }}. }
 21	            </p>
 22	          } @else {
 23	            <p class="mb-0">Please review the figures below and record your response. Nothing is paid out differently because of your answer — it records whether you agree, and anything you disagree with goes to HR.</p>
 24	          }
 25	        </div>
 26	        <div class="popup-banner mb-3">
 27	          <div class="banner-row">
 28	            <div><span class="banner-label">Statement No.</span><span class="banner-value">{{ case.caseNo }}</span></div>
 29	            <div><span class="banner-label">Name</span><span class="banner-value">{{ case.employeeName }}</span></div>
 30	            <div><span class="banner-label">Employee Code</span><span class="banner-value">{{ case.employeeCode }}</span></div>
 31	            <div><span class="banner-label">Last Working Day</span><span class="banner-value">{{ case.lastWorkingDate ? (case.lastWorkingDate | date: 'dd-MMM-yyyy') : '—' }}</span></div>
 32	          </div>
 33	          <div class="banner-row mt-2">
 34	            <div><span class="banner-label">Total Paid</span><span class="banner-value">{{ case.totalEarnings ?? 0 | number: '1.2-2' }}</span></div>
 35	            <div><span class="banner-label">Total Deducted</span><span class="banner-value">{{ case.totalDeductions ?? 0 | number: '1.2-2' }}</span></div>
 36	            <div>
 37	              <span class="banner-label">{{ (case.netPayable ?? 0) < 0 ? 'Recoverable from You' : 'Net Payable to You' }}</span>
 38	              <span class="banner-value" [style.color]="(case.netPayable ?? 0) < 0 ? '#7f1d1d' : '#14532d'" style="font-size:18px;">{{ (case.netPayable ?? 0) < 0 ? -(case.netPayable ?? 0) : (case.netPayable ?? 0) | number: '1.2-2' }}</span>
 39	            </div>
 40	            @if (case.complianceWindowEnd) {
 41	              <div><span class="banner-label">Query Window Closes</span><span class="banner-value">{{ case.complianceWindowEnd | date: 'dd-MMM-yyyy' }}</span></div>
 42	            }
 43	          </div>
 44	        </div>
 45	        <div class="section-card">
 46	          <div class="section-header">What You Are Being Paid</div>
 47	          <div class="section-body">
 48	            <app-common-grid
 49	              [dataSource]="lines"
 50	              [columns]="columns"
 51	              [storageKey]="'fnfMyStatementGrid'"
 52	              [showAddButton]="false"
 53	              [allowRowEdit]="false"
 54	              [allowRowDelete]="false"
 55	              [fillViewport]="false"
 56	              [enableStateStoring]="false"
 57	            ></app-common-grid>
 58	          </div>
 59	        </div>
 60	        <div class="section-card">
 61	          <div class="section-header">Your Response</div>
 62	          <div class="section-body">
 63	            <p class="hint-text mb-2">
 64	              If anything looks wrong, choose <b>Accept with Query</b> or <b>Not Accepted</b> and say what it is — HR sees your words exactly as you write them.
 65	            </p>
 66	            <dx-text-area
 67	              [(value)]="remarks"
 68	              [height]="80"
 69	              [disabled]="alreadyResponded"
 70	              [maxLength]="1000"
 71	              placeholder="For example: leave encashment shows 18 days, my record says 20."
 72	            ></dx-text-area>
 73	            @if (!alreadyResponded) {
 74	              <div class="popup-actions">
 75	                <dx-button text="Not Accepted" type="danger" stylingMode="outlined" [disabled]="responding" (onClick)="respond('Not Accepted')"></dx-button>
 76	                <dx-button text="Accept with Query" stylingMode="outlined" [disabled]="responding" (onClick)="respond('Accepted with Pending Query')"></dx-button>
 77	                <dx-button text="Accept" type="success" stylingMode="contained" [disabled]="responding" (onClick)="respond('Accepted')"></dx-button>
 78	              </div>
 79	            }
 80	          </div>
 81	        </div>
 82	      }
 83	    </div>
 84	  </div>
 85	</div>

