    public async Task<ResponseModel> GetSettlementDetailsAsync(long caseId)
    {
        var res = new ResponseModel();
        try
        {
            var list = await _repository.GetSettlementDetailsAsync(caseId);
            return Success(res, "Fetched settlement lines.", list);
        }
        catch (Exception e)
        {
            _logger.LogError(e, "Exception while fetching settlement lines for case {Id}", caseId);
            return Fail(res, HttpStatusCode.InternalServerError, e.Message);
        }
    }

    public async Task<List<FnfSettlementDetailModel>> GetSettlementDetailsAsync(long caseId)
    {
        const string sql = @"
            SELECT FNFSettlementDetailID AS FnfSettlementDetailId, FNFSettlementID AS FnfSettlementId,
                   ComponentType, SalaryHeadMasterID AS SalaryHeadMasterId, [Add/Deduct] AS AddDeduct,
                   Days, Rate, Amount, IsAuto, Remarks, SortOrder
            FROM   HR_FNFSettlementDetail WHERE FNFSettlementID = @CaseId
            ORDER  BY SortOrder, FNFSettlementDetailID";
        var res = await _repo.QueryAsync<FnfSettlementDetailModel>(sql, new { CaseId = caseId });
        return res.ToList();
    }

